#include <stdio.h>
#include <stdbool.h>

int count = 0;
void backtrack(int r, int n, int cols, int d1, int d2) {
    if (r == n) { count++; return; }
    int available = ((1 << n) - 1) & ~(cols | d1 | d2);
    while (available) {
        int bit = available & -available;
        available &= available - 1;
        backtrack(r + 1, n, cols | bit, (d1 | bit) << 1, (d2 | bit) >> 1);
    }
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    count = 0;
    backtrack(0, n, 0, 0, 0);
    printf("%d\n", count);
    return 0;
}
